def grade_coding(text):
    code = extract_code(text)
    if not code.strip():
        return 0.0
    return _run_code(code)

def _run_code(code):
    tid = _run_code.tid
    tests = DATA["coding"][tid]["tests"]
    with tempfile.TemporaryDirectory() as td:
        cf = os.path.join(td, "cand.py")
        open(cf, "w").write(code)
        tf = os.path.join(td, "tests.json")
        open(tf, "w").write(json.dumps(tests))
        hf = os.path.join(td, "harness.py")
        open(hf, "w").write(HARNESS)
        try:
            r = subprocess.run([sys.executable, hf, cf, tf],
                               capture_output=True, text=True, timeout=20)
