def _norm_words(text):
    return re.findall(r"[\w'’-]+", text)

def _lines(text):
    return [l for l in text.split("\n")]

def _nonempty_lines(text):
    return [l for l in text.split("\n") if l.strip()]

def _paragraphs(text):
    paras = [p for p in re.split(r"\n\s*\n", text.strip()) if p.strip()]
    return paras

def _sentences(text):
    s = re.sub(r"\s+", " ", text.strip())
    parts = re.split(r"(?<=[.!?])\s+", s)
    return [p for p in parts if p.strip()]

def _word_count(text):
    return len(_norm_words(text))

def _tables(text):
    tables = []
    cur = []
    for l in _lines(text):
        if l.strip().startswith("|"):
            cur.append([c.strip() for c in l.strip().strip("|").split("|")])
        else:
            if cur:
                tables.append(cur)
                cur = []
    if cur:
        tables.append(cur)
    return tables

def _nums_in(text):
    s = text.replace(",", "")
    return [float(m) for m in re.findall(r"-?\d+(?:\.\d+)?(?:[eE]-?\d+)?", s)]

def _contains_count(text, s, case_insensitive=True):
    if case_insensitive:
        return text.lower().count(s.lower())
    return text.count(s)

def run_check(ch, text):
    t = ch["t"]
    if t == "word_count_range":
        return ch["lo"] <= _word_count(text) <= ch["hi"]
    if t == "word_count_max":
        return _word_count(text) <= ch["n"]
    if t == "word_count_min":
        return _word_count(text) >= ch["n"]
    if t == "contains":
        n = _contains_count(text, ch["s"], not ch.get("case_sensitive", False) and not ch.get("exact", False) or not ch.get("case_sensitive", not ch.get("exact", False)))
        # count occurrences; for word-like short strings count non-overlapping
        return n >= ch["n"]
    if t == "contains_at_most":
        return _contains_count(text, ch["s"], True) <= ch["n"]
    if t == "not_contains":
        return ch["s"].lower() not in text.lower()
    if t == "contains_case_sensitive":
        return text.count(ch["s"]) >= ch["n"]
    if t == "all_lower":
        return text == text.lower()
    if t == "no_char":
        ci = ch.get("case_insensitive", False)
        c = ch["ch"]
        if ci:
            return c.lower() not in text.lower()
        return c not in text
    if t == "title_line":
        lines = _nonempty_lines(text)
        return bool(lines) and lines[0].strip() == ch["s"]
    if t == "numbered_list":
        pat = re.compile(r"^\s*\d+[.)]")
        n = sum(1 for l in _lines(text) if pat.match(l))
        return n == ch["n"]
    if t == "numbered_line_word_max":
        pat = re.compile(r"^\s*\d+[.)]\s*(.*)$")
        for l in _lines(text):
            m = pat.match(l)
            if m:
                if _word_count(m.group(1)) > ch["n"]:
                    return False
        return True
    if t == "bullets":
        n = sum(1 for l in _lines(text) if re.match(r"^\s*[-*] ", l))
        return n == ch["n"]
    if t == "bullet_word_count":
        bl = [l for l in _lines(text) if re.match(r"^\s*[-*] ", l)]
        if len(bl) == 0:
            return False
        return all(_word_count(l) == ch["n"] for l in bl) and len(bl) == ch["n"]
    if t == "md_headers":
        n = sum(1 for l in _lines(text) if l.startswith("## "))
        return n == ch["n"]
    if t == "md_headers_exact":
        seen = [l.strip() for l in _lines(text) if l.strip().startswith("###")]
        return seen == ch["headers"]
    if t == "header_seq":
        seen = [l.strip() for l in _lines(text) if l.strip().startswith("##")]
        return seen == ch["headers"]
    if t == "section_bullets":
        lines = _lines(text)
        idx = next((i for i, l in enumerate(lines) if l.strip() == ch["header"]), None)
        if idx is None:
            return False
        count = 0
        for l in lines[idx+1:]:
            if l.strip().startswith("#"):
                break
            if re.match(r"^\s*[-*] ", l):
                count += 1
        return count >= ch["n"]
    if t == "paragraphs":
        return len(_paragraphs(text)) == ch["n"]
    if t == "para_lines":
        paras = _paragraphs(text)
        if len(paras) <= ch["p"]:
            return False
        return len([l for l in _nonempty_lines(paras[ch["p"]])]) == ch["n"]
    if t == "para_contains":
        paras = _paragraphs(text)
        if len(paras) <= ch["p"]:
            return False
        return ch["s"].lower() in paras[ch["p"]].lower()
    if t == "para_starts":
        paras = _paragraphs(text)
        if len(paras) <= ch["p"]:
            return False
        return paras[ch["p"]].strip().lower().startswith(ch["s"])
    if t == "line_contains_all":
        paras = _paragraphs(text)
        if len(paras) <= ch["para"]:
            return False
        lines = _nonempty_lines(paras[ch["para"]])
        hits = sum(1 for l in lines if ch["s"].lower() in l.lower())
        return hits >= ch["n"]
    if t == "nlines":
        n = len(_nonempty_lines(text))
        if "n_min" in ch and n < ch["n_min"]:
            return False
        if "n_max" in ch and n > ch["n_max"]:
            return False
        if "n" in ch and n != ch["n"]:
            return False
        return True
    if t == "line_prefix":
        lines = _nonempty_lines(text)
        if len(lines) <= ch["line"]:
            return False
        return lines[ch["line"]].strip().startswith(ch["p"])
    if t == "acrostic":
        lines = _nonempty_lines(text)
        if len(lines) < len(ch["word"]):
            return False
        letters = [l.strip()[0].upper() for l in lines[:len(ch["word"])]]
        return "".join(letters) == ch["word"].upper()
    if t == "line_word_max":
        return all(_word_count(l) <= ch["n"] for l in _nonempty_lines(text))
    if t == "ends_with_word":
        return text.rstrip().endswith(ch["s"])
    if t == "sentence_count":
        return len(_sentences(text)) == ch["n"]
    if t == "each_sentence_starts":
        return all(s.lower().startswith(ch["p"]) for s in _sentences(text))
    if t == "first_sentence_longer":
        s = _sentences(text)
        return len(s) == 2 and _word_count(s[0]) > _word_count(s[1])
    if t == "endings_only_periods":
        return not re.search(r"[!?]", text)
    if t == "no_url":
        return "http://" not in text and "https://" not in text and "www." not in text
    if t == "ascii_only":
        return all(ord(c) < 128 for c in text)
    if t == "json_keys":
        try:
            obj = json.loads(text.strip())
        except Exception:
            return False
        return isinstance(obj, dict) and set(obj.keys()) == set(ch["keys"])
    if t == "json_str_contains":
        try:
            obj = json.loads(text.strip())
            return ch["s"].lower() in str(obj.get(ch["key"], "")).lower()
        except Exception:
            return False
    if t == "json_num_equals":
        try:
            obj = json.loads(text.strip())
