            return isinstance(v, (int, float)) and abs(float(v) - ch["v"]) < 1e-9
        except Exception:
            return False
    if t == "json_str_equals":
        try:
            obj = json.loads(text.strip())
            return str(obj.get(ch["key"], "")) == ch["s"]
        except Exception:
            return False
    if t == "json_array_len":
        try:
            obj = json.loads(text.strip())
            v = obj.get(ch["key"])
            return isinstance(v, list) and len(v) == ch["n"]
        except Exception:
            return False
    if t == "json_readings_increasing":
        try:
            obj = json.loads(text.strip())
            v = obj.get("readings")
            if not isinstance(v, list) or len(v) != ch["n"]:
                return False
            nums = [float(x) for x in v]
            return all(0 <= x <= 100 for x in nums) and all(nums[i] < nums[i+1] for i in range(len(nums)-1))
        except Exception:
            return False
    if t == "json_sensor_pattern":
        try:
            obj = json.loads(text.strip())
            return bool(re.match(r"^S-\d{3}$", str(obj.get("sensor", ""))))
        except Exception:
            return False
    if t == "qa_pairs":
        qlines = [l for l in _lines(text) if l.strip().startswith("Q:")]
        alines = [l for l in _lines(text) if l.strip().startswith("A:")]
        qend = [l for l in qlines if l.strip().endswith("?")]
        return len(qend) == ch["n"] and len(qlines) == ch["n"] and len(alines) == ch["n"]
    if t == "hashtag_line":
        hash_lines = [l for l in _lines(text) if "#" in l]
        if len(hash_lines) != 1:
            return False
        tags = re.findall(r"#\w+", hash_lines[0])
        rest = re.sub(r"#\w+", "", hash_lines[0]).strip()
        return len(tags) == ch["n"] and len(rest.split()) == 0
    if t == "table_count":
        return len(_tables(text)) == ch["n"]
    if t == "table_rows":
        tables = _tables(text)
        if len(tables) <= ch.get("table", 0):
            return False
        tb = tables[ch.get("table", 0)]
        # data rows = rows minus header minus separator rows
        data = [r for r in tb[1:] if not all(re.match(r"^:?-{2,}:?$", c) for c in r if c)]
        return len(data) == ch["n"]
    if t == "table_headers":
        tables = _tables(text)
        if len(tables) <= ch.get("table", 0):
            return False
        return all(h in tables[ch.get("table", 0)][0] for h in ch["headers"])
    if t == "table_headers_any":
        return any(all(h in tb[0] for h in ch["headers"]) for tb in _tables(text) if tb)
    if t == "numbers_present":
        nums = _nums_in(text)
        ok = 0
        for v in ch["values"]:
            if any(abs(n - v) <= ch["tol"] for n in nums):
                ok += 1
        return ok / len(ch["values"])
    if t == "sum_pct":
        tables = _tables(text)
        if not tables:
